      const allocations=await client.query(`select a.*,p.version report_version,p.allocated_good_qty,p.reversed report_reversed from production_completion_report_allocations a join production_report_receipt_projections p on p.report_id=a.report_id where a.completion_id=$1 order by a.report_id for update of a,p`,[completionId]);if(!allocations.rows.length)throw new ProductionError("PRODUCTION_COMPLETION_LEGACY_UNALLOCATED","完工缺少可恢复的报工分配，不能冲销",409);if(!(await client.query("select bool_and(not p.reversed and p.allocated_good_qty>=a.quantity) ok from production_completion_report_allocations a join production_report_receipt_projections p on p.report_id=a.report_id where a.completion_id=$1",[completionId])).rows[0].ok)throw new ProductionError("PRODUCTION_REPORT_VERSION_CONFLICT","报工可入库投影无法安全恢复",409);
      const completedQty=String((await client.query("select sum(quantity)::text quantity from production_completion_report_allocations where completion_id=$1",[completionId])).rows[0].quantity);const inventory=await this.inventory.reverseInTransaction(client,Number(completion.inventory_adjustment_id),this.inventoryMeta(meta,"PRODUCTION_COMPLETION_REVERSED"),{reason,expected_balance_versions:input.expected_balance_versions});await this.fault?.("after_completion_reversal_inventory");
